import { t as client } from "../../../../chunks/prisma.js";
import { t as getActiveMembership } from "../../../../chunks/group-membership.js";
import { t as getFormatter } from "../../../../chunks/i18n.js";
import { s as requireLogin } from "../../../../chunks/auth.js";
import { error, redirect } from "@sveltejs/kit";
// src/routes/wishlists/[username]/+page.server.ts
var load = async ({ params }) => {
	const user = requireLogin();
	const $t = await getFormatter();
	const activeMembership = await getActiveMembership(user);
	const list = await client.list.findFirst({
		select: { id: true },
		where: {
			owner: { username: params.username },
			groupId: activeMembership.groupId
		}
	});
	if (!list) error(404, $t("errors.list-not-found"));
	redirect(302, `/lists/${list.id}`);
};
export { load };
